import time

def retry(fn, attempts, base_delay, sleep=None):
    last_exception = None
    for i in range(1, attempts + 1):
        try:
            return fn()
        except Exception as e:
            last_exception = e
            if i < attempts:
                delay = base_delay * (2 ** (i - 1))
                if sleep is None:
                    time.sleep(delay)
                else:
                    sleep(delay)
    raise last_exception
